package com.panaderia.service; import com.panaderia.dao.MovimientoStockDAO; import com.panaderia.model.MovimientoStock; import java.sql.SQLException; import java.util.*;
public class StockService {private final MovimientoStockDAO dao=new MovimientoStockDAO(); public void registrar(int id,String tipo,int cantidad,String obs)throws SQLException{if(id<=0)throw new IllegalArgumentException("Seleccione un producto.");if(!tipo.equals("ENTRADA")&&!tipo.equals("SALIDA"))throw new IllegalArgumentException("Seleccione un tipo de movimiento válido.");if(cantidad<=0)throw new IllegalArgumentException("La cantidad debe ser mayor a 0.");dao.registrar(id,tipo,cantidad,obs);}public List<MovimientoStock> listar()throws SQLException{return dao.listar();}}
